'use strict';
/* Actual wind of the simulation, taken from the OFP of the flight (js/data/ofp.js, generated by tools/ofp/mkofp.py).
   OFP winds are true direction / knots: a climb table and a descent table by flight level, and a table of five levels at every waypoint.
   The flight flies the wind of its OFP (matched by flight number, else by FROM/TO); without an OFP only the local surface wind is used.
   The FMS winds on the CLIMB / CRUISE / DESCENT WIND pages are the forecast and stay the pilot's entries (or the WIND REQUEST uplink). */
const WX={on:true,flt:null,surface:{},frozenWind:null};
function ofpOf(flt){return typeof OFPS!=='undefined'&&OFPS.find(o=>o.flt===flt)||null}
function ofpFor(from,to){return typeof OFPS!=='undefined'&&OFPS.find(o=>o.from===from&&o.to===to)||null}
/* the OFP whose winds are flown: the one chosen on the FLIGHT PLANS tab, else by flight number, else by city pair */
function wxOfp(){const p=S.active;if(!p)return null;const f=p.legs[0].id,t=p.legs[idxK(p,'dest')].id,ok=o=>o&&o.from===f&&o.to===t?o:null;
  return ok(ofpOf(WX.flt))||ok(ofpOf(I().flt))||ofpFor(f,t)}
const wvec=(d,s)=>[s*Math.sin(d*D2R),s*Math.cos(d*D2R)],wpol=v=>{const s=Math.hypot(v[0],v[1]);return{dir:s<0.05?0:(Math.atan2(v[0],v[1])/D2R+360)%360,spd:s}};
/* wind in a table [[FL, dir, spd], ...] at an altitude: interpolated between the two levels, the end values outside */
function wxTable(T,alt){const L=T.slice().sort((a,b)=>a[0]-b[0]),fl=alt/100;if(!L.length)return[0,0];
  if(fl<=L[0][0])return wvec(L[0][1],L[0][2]);if(fl>=L[L.length-1][0])return wvec(L[L.length-1][1],L[L.length-1][2]);
  for(let i=1;i<L.length;i++)if(fl<=L[i][0]){const a=wvec(L[i-1][1],L[i-1][2]),b=wvec(L[i][1],L[i][2]),k=(fl-L[i-1][0])/(L[i][0]-L[i-1][0]);return[a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k]}
  return[0,0]}
/* A stable random surface wind for each airport, chosen again when a new flight starts. */
function surfaceWind(pos){const p=S.active;if(!p)return{dir:0,spd:0};const from=p.legs[0].id,to=p.legs[idxK(p,'dest')].id;
  const airports=[from,to].map(id=>({id,a:DB.apt[id]})).filter(x=>x.a);if(!airports.length)return{dir:0,spd:0};
  const nearest=airports.reduce((a,b)=>gc(pos,a.a.pos)<=gc(pos,b.a.pos)?a:b).id;
  return WX.surface[nearest]||(WX.surface[nearest]={dir:Math.random()*360,spd:3+Math.random()*16})}
/* True wind {dir, spd}. The stable surface wind applies through 1500 ft AAL, then blends into the OFP or frozen wind by 3000 ft AAL. */
function windAt(pos,alt,aal,phase){if(!WX.on||!pos)return{dir:0,spd:0};const low=surfaceWind(pos);if(aal!=null&&aal<=1500)return low;
  if(WX.frozenWind){const k=aal==null?1:Math.max(0,Math.min(1,(aal-1500)/1500)),lo=wvec(low.dir,low.spd),hi=wvec(WX.frozenWind.dir,WX.frozenWind.spd);
    return wpol([lo[0]*(1-k)+hi[0]*k,lo[1]*(1-k)+hi[1]*k])}
  const o=wxOfp();const w=o&&o.wind;let v=null;
  if(!w){const k=aal==null?1:Math.max(0,Math.min(1,(aal-1500)/1500));return wpol(wvec(low.dir,low.spd*(1-k)))}
  let best=null,bd=1e9;for(const e of w.enr){const d=gc(pos,e.pos);if(d<bd){bd=d;best=e}}
  const ph=phase||S.phase,clb=['PREFLIGHT','TAKEOFF','TO','CLB'].includes(ph),des=['DES','APPR','GA','DONE'].includes(ph);
  if(best){const lo=Math.min(...best.lv.map(x=>x[0]))*100,hi=Math.max(...best.lv.map(x=>x[0]))*100;
    if(alt>=lo-1000&&alt<=hi+1000)v=wxTable(best.lv,alt)}
  if(!v)v=clb&&w.clb.length?wxTable(w.clb,alt):des&&w.des.length?wxTable(w.des,alt):best?wxTable(best.lv,alt):[0,0];
  const k=aal==null?1:Math.min(1,(aal-1500)/1500),lo=wvec(low.dir,low.spd);
  return wpol([lo[0]*(1-k)+v[0]*k,lo[1]*(1-k)+v[1]*k])}
/* ground track flown with a true heading in a wind (HDG mode) */
function trkOfHdg(h,tas,w){if(!w||w.spd<0.5)return h;const a=wvec(h,Math.max(60,tas)),b=wvec(w.dir,w.spd);return(Math.atan2(a[0]-b[0],a[1]-b[1])/D2R+360)%360}
/* heading and ground speed on a ground track in a wind */
function crabOf(trk,tas,w){if(!w||w.spd<0.5)return{hdg:trk,gs:tas};const rel=(w.dir-trk)*D2R,c=Math.asin(Math.max(-0.6,Math.min(0.6,w.spd*Math.sin(rel)/Math.max(60,tas))));
  return{hdg:(trk+c/D2R+360)%360,gs:Math.max(40,tas*Math.cos(c)-w.spd*Math.cos(rel))}}
/* FMS forecast winds from the OFP (WIND REQUEST uplink): climb, cruise at the levels around the cruise level, descent */
function wxUplink(){const o=wxOfp();if(!o)return false;const w=o.wind,m=x=>({dir:x[1]%360,spd:x[2],alt:x[0]*100});
  S.wind.clb=w.clb.slice(0,5).map(m).sort((a,b)=>a.alt-b.alt);S.wind.des=w.des.slice(0,5).map(m).sort((a,b)=>b.alt-a.alt);
  const crz=(I().crz||o.fl),e=w.enr.filter(x=>x.lv.some(l=>Math.abs(l[0]-crz)<=20)),mid=e[Math.floor(e.length/2)];
  S.wind.crz=mid?mid.lv.slice().sort((a,b)=>Math.abs(a[0]-crz)-Math.abs(b[0]-crz)).slice(0,4).map(m).sort((a,b)=>a.alt-b.alt):[];return true}
['CLBW','CRZW','DESW'].forEach(pg=>{const l0=P[pg].lsk;P[pg].lsk=function(s,n){if(s==='R'&&n===2){if(!wxUplink())return err('NO ANSWER TO REQUEST');msg2('WIND DATA UPLINK');return ok()}return l0.call(this,s,n)}});
window.__wx={WX,windAt,wxOfp,trkOfHdg,crabOf,wxUplink};
